export type Tool = 'pencil' | 'rectangle' | 'circle' | 'select' | 'text';

export type AIModel = 'nano-banana' | 'nano-banana-pro';

export interface RefinedImage {
  id: string;
  dataUrl: string;
  base64: string;
  sketchBase64: string;
  prompt: string;
  timestamp: number;
  status: 'loading' | 'ready' | 'error';
  model: AIModel;
}

import React, { useRef, useEffect, useImperativeHandle, forwardRef, useState } from 'react';
import * as fabric from 'fabric';
import { Tool } from '../types';

interface DrawingCanvasProps {
  tool: Tool;
  color: string;
  brushSize: number;
  onContentChange?: (isEmpty: boolean) => void;
}

export interface DrawingCanvasHandle {
  clear: () => void;
  deleteSelected: () => void;
  getCanvasData: () => string;
  loadFromDataUrl: (dataUrl: string) => void;
  addImage: (dataUrl: string) => void;
  clearBackground: () => void;
  undo: () => void;
  redo: () => void;
  copy: () => void;
  paste: () => void;
  duplicate: () => void;
  bringForward: () => void;
  sendBackwards: () => void;
}

const BASE_WIDTH = 1600;
const BASE_HEIGHT = 900;

export const DrawingCanvas = forwardRef<DrawingCanvasHandle, DrawingCanvasProps>(({ tool, color, brushSize, onContentChange }, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fabricRef = useRef<fabric.Canvas | null>(null);
  const [isEmpty, setIsEmpty] = useState(true);
  const [hasInteracted, setHasInteracted] = useState(false);

  const isInteracting = useRef(false);
  const isDrawingStraightLine = useRef(false);
  const currentShape = useRef<fabric.Object | null>(null);
  const lineStartPoint = useRef({ x: 0, y: 0 });

  const undoStack = useRef<string[]>([]);
  const redoStack = useRef<string[]>([]);
  const isHandlingHistory = useRef(false);

  const clipboard = useRef<fabric.Object | null>(null);

  const checkEmpty = () => {
    if (!fabricRef.current) return;
    const objectCount = fabricRef.current.getObjects().length;
    const empty = objectCount === 0;
    setIsEmpty(empty);
    if (empty) setHasInteracted(false);
    onContentChange?.(empty);
  };

  const saveToHistory = () => {
    if (isHandlingHistory.current || !fabricRef.current) return;
    checkEmpty();
    const currentState = JSON.stringify(fabricRef.current.toObject());
    const lastState = undoStack.current[undoStack.current.length - 1];
    if (currentState !== lastState) {
      undoStack.current.push(currentState);
      redoStack.current = [];
      if (undoStack.current.length > 50) undoStack.current.shift();
    }
  };

  const getVirtualPointer = (e: any) => {
    if (!fabricRef.current || !containerRef.current) return { x: 0, y: 0 };
    const nativeEvent = e.e || e;
    const rect = fabricRef.current.getElement().getBoundingClientRect();
    const clientX = nativeEvent.clientX || (nativeEvent.touches && nativeEvent.touches[0]?.clientX) || 0;
    const clientY = nativeEvent.clientY || (nativeEvent.touches && nativeEvent.touches[0]?.clientY) || 0;
    const scaleX = BASE_WIDTH / rect.width;
    const scaleY = BASE_HEIGHT / rect.height;
    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  };

  useEffect(() => {
    if (!canvasRef.current || !containerRef.current) return;

    const figmaBlue = '#18A0FB';
    fabric.Object.prototype.set({
      transparentCorners: false,
      cornerColor: figmaBlue,
      cornerStrokeColor: figmaBlue,
      borderColor: figmaBlue,
      borderScaleFactor: 1,
      cornerSize: 10,
      cornerStyle: 'rect',
      padding: 0,
      hasBorders: true,
      hasControls: true,
      uniformScaling: true,
    });

    const canvas = new fabric.Canvas(canvasRef.current, {
      backgroundColor: '#000000',
      selection: true,
      preserveObjectStacking: true,
      enableRetinaScaling: true,
      fireRightClick: true,
      uniScaleKey: 'shiftKey',
    });

    fabricRef.current = canvas;
    canvas.on('object:modified', saveToHistory);
    canvas.on('path:created', saveToHistory);
    canvas.on('object:removed', saveToHistory);
    canvas.on('object:added', checkEmpty);

    const resizeCanvas = () => {
      if (!containerRef.current || !fabricRef.current) return;
      const w = containerRef.current.offsetWidth;
      const h = w * (9/16);
      fabricRef.current.setDimensions({ width: w, height: h });
      const scale = w / BASE_WIDTH;
      fabricRef.current.setZoom(scale);
      fabricRef.current.renderAll();
    };

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    saveToHistory();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      canvas.dispose();
    };
  }, []);

  useEffect(() => {
    const canvas = fabricRef.current;
    if (!canvas) return;

    canvas.isDrawingMode = tool === 'pencil';
    if (canvas.isDrawingMode) {
      const brush = new fabric.PencilBrush(canvas);
      brush.width = brushSize;
      brush.color = color;
      canvas.freeDrawingBrush = brush;
    }

    canvas.selection = tool === 'select';
    canvas.forEachObject(obj => {
      obj.selectable = tool === 'select' || tool === 'text';
      obj.evented = tool === 'select' || tool === 'text';
    });

    const handleMouseDown = (o: any) => {
      if (tool === 'select') return;
      isInteracting.current = true;
      setHasInteracted(true);
      const p = getVirtualPointer(o);
      lineStartPoint.current = p;

      if (tool === 'text') {
        const text = new fabric.IText('Text', {
          left: p.x, top: p.y,
          fontFamily: 'Google Sans Text', fontSize: 32, fill: color,
          selectable: true, evented: true, originX: 'left', originY: 'top'
        });
        canvas.add(text);
        canvas.setActiveObject(text);
        text.enterEditing();
        text.selectAll();
        isInteracting.current = false;
        saveToHistory();
        return;
      }

      if (tool === 'pencil' && o.e.shiftKey) {
        isDrawingStraightLine.current = true;
        canvas.isDrawingMode = false;
        const line = new fabric.Line([p.x, p.y, p.x, p.y], {
          stroke: color, strokeWidth: brushSize, strokeLineCap: 'round', selectable: false, evented: false
        });
        currentShape.current = line;
        canvas.add(line);
      } else if (tool === 'rectangle') {
        const rect = new fabric.Rect({
          left: p.x, top: p.y, width: 0, height: 0,
          fill: 'transparent', stroke: color, strokeWidth: 3, 
          selectable: false, evented: false, originX: 'left', originY: 'top'
        });
        currentShape.current = rect;
        canvas.add(rect);
      } else if (tool === 'circle') {
        const circle = new fabric.Circle({
          left: p.x, top: p.y, radius: 0,
          fill: 'transparent', stroke: color, strokeWidth: 3, 
          selectable: false, evented: false, originX: 'left', originY: 'top'
        });
        currentShape.current = circle;
        canvas.add(circle);
      }

      if (tool !== 'pencil' && tool !== 'text') {
        const onMove = (e: MouseEvent) => {
          if (!currentShape.current) return;
          const mp = getVirtualPointer(e);
          const start = lineStartPoint.current;

          if (tool === 'pencil' && isDrawingStraightLine.current) {
            (currentShape.current as fabric.Line).set({ x2: mp.x, y2: mp.y });
          } else if (tool === 'rectangle') {
            const rect = currentShape.current as fabric.Rect;
            rect.set({
              left: Math.min(start.x, mp.x),
              top: Math.min(start.y, mp.y),
              width: Math.abs(start.x - mp.x),
              height: Math.abs(start.y - mp.y)
            });
          } else if (tool === 'circle') {
            const circle = currentShape.current as fabric.Circle;
            const dx = mp.x - start.x;
            const dy = mp.y - start.y;
            const size = Math.max(Math.abs(dx), Math.abs(dy));
            circle.set({
              radius: size / 2,
              left: dx >= 0 ? start.x : start.x - size,
              top: dy >= 0 ? start.y : start.y - size
            });
          }
          currentShape.current.setCoords();
          canvas.renderAll();
        };

        const onUp = () => {
          window.removeEventListener('mousemove', onMove);
          window.removeEventListener('mouseup', onUp);
          if (currentShape.current) {
            currentShape.current.set({ selectable: true, evented: true });
            currentShape.current.setCoords();
          }
          isDrawingStraightLine.current = false;
          isInteracting.current = false;
          currentShape.current = null;
          if (fabricRef.current && tool === 'pencil') fabricRef.current.isDrawingMode = true;
          saveToHistory();
        };

        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
      }
    };

    const handleMouseUp = () => {
      if (isInteracting.current && tool === 'pencil' && !isDrawingStraightLine.current) {
        isInteracting.current = false;
        saveToHistory();
      }
    };

    canvas.on('mouse:down', handleMouseDown);
    canvas.on('mouse:up', handleMouseUp);
    return () => {
      canvas.off('mouse:down', handleMouseDown);
      canvas.off('mouse:up', handleMouseUp);
    };
  }, [tool, color, brushSize]);

  useImperativeHandle(ref, () => ({
    clear: () => {
      fabricRef.current?.clear();
      if (fabricRef.current) fabricRef.current.backgroundColor = '#000000';
      fabricRef.current?.renderAll();
      saveToHistory();
    },
    undo: () => {
      if (undoStack.current.length <= 1 || !fabricRef.current) return;
      isHandlingHistory.current = true;
      const current = undoStack.current.pop()!;
      redoStack.current.push(current);
      const previous = undoStack.current[undoStack.current.length - 1];
      fabricRef.current.loadFromJSON(previous).then(() => {
        fabricRef.current?.renderAll();
        isHandlingHistory.current = false;
        checkEmpty();
      });
    },
    redo: () => {
      if (redoStack.current.length === 0 || !fabricRef.current) return;
      isHandlingHistory.current = true;
      const next = redoStack.current.pop()!;
      undoStack.current.push(next);
      fabricRef.current.loadFromJSON(next).then(() => {
        fabricRef.current?.renderAll();
        isHandlingHistory.current = false;
        checkEmpty();
      });
    },
    deleteSelected: () => {
      const objs = fabricRef.current?.getActiveObjects();
      if (objs && objs.length > 0) {
        fabricRef.current?.discardActiveObject();
        objs.forEach(o => fabricRef.current?.remove(o));
        fabricRef.current?.renderAll();
        saveToHistory();
      }
    },
    getCanvasData: () => {
      if (!fabricRef.current) return '';
      const scale = fabricRef.current.getZoom();
      return fabricRef.current.toDataURL({ format: 'png', multiplier: 1 / scale });
    },
    loadFromDataUrl: async (dataUrl: string) => {
      if (!fabricRef.current) return;
      try {
        const img = await fabric.FabricImage.fromURL(dataUrl);
        const s = Math.min((BASE_WIDTH * 0.5) / img.width!, (BASE_HEIGHT * 0.5) / img.height!);
        img.set({ scaleX: s, scaleY: s, left: BASE_WIDTH / 2, top: BASE_HEIGHT / 2, originX: 'center', originY: 'center', selectable: true });
        fabricRef.current.add(img);
        fabricRef.current.setActiveObject(img);
        fabricRef.current.renderAll();
        saveToHistory();
      } catch (err) { console.error(err); }
    },
    addImage: async (dataUrl: string) => {
      if (!fabricRef.current) return;
      try {
        const img = await fabric.FabricImage.fromURL(dataUrl);
        const s = Math.min((BASE_WIDTH * 0.5) / img.width!, (BASE_HEIGHT * 0.5) / img.height!);
        img.set({
          scaleX: s, scaleY: s,
          left: BASE_WIDTH / 2, top: BASE_HEIGHT / 2,
          originX: 'center', originY: 'center',
          selectable: true
        });
        fabricRef.current.add(img);
        fabricRef.current.setActiveObject(img);
        fabricRef.current.renderAll();
        saveToHistory();
      } catch (err) { console.error('Failed to add image:', err); }
    },
    clearBackground: () => {
      const bgs = fabricRef.current?.getObjects().filter(o => (o as any).isBackground);
      bgs?.forEach(bg => fabricRef.current?.remove(bg));
      fabricRef.current?.renderAll();
      saveToHistory();
    },
    copy: async () => {
      const activeObject = fabricRef.current?.getActiveObject();
      if (activeObject) {
        const cloned = await activeObject.clone();
        clipboard.current = cloned;
      }
    },
    paste: async () => {
      if (!clipboard.current || !fabricRef.current) return;
      const clonedObj = await clipboard.current.clone();
      fabricRef.current.discardActiveObject();
      clonedObj.set({
        left: clonedObj.left! + 20,
        top: clonedObj.top! + 20,
        evented: true,
      });
      if (clonedObj instanceof fabric.ActiveSelection) {
        clonedObj.canvas = fabricRef.current;
        clonedObj.forEachObject((obj) => {
          fabricRef.current?.add(obj);
        });
        clonedObj.setCoords();
      } else {
        fabricRef.current.add(clonedObj);
      }
      clipboard.current.set({
        left: clipboard.current.left! + 20,
        top: clipboard.current.top! + 20,
      });
      fabricRef.current.setActiveObject(clonedObj);
      fabricRef.current.requestRenderAll();
      saveToHistory();
    },
    duplicate: async () => {
      const activeObject = fabricRef.current?.getActiveObject();
      if (!activeObject || !fabricRef.current) return;

      const clonedObj = await activeObject.clone();
      fabricRef.current.discardActiveObject();
      clonedObj.set({
        left: clonedObj.left! + 20,
        top: clonedObj.top! + 20,
        evented: true,
      });

      if (clonedObj instanceof fabric.ActiveSelection) {
        clonedObj.canvas = fabricRef.current;
        clonedObj.forEachObject((obj) => {
          fabricRef.current?.add(obj);
        });
        clonedObj.setCoords();
      } else {
        fabricRef.current.add(clonedObj);
      }
      fabricRef.current.setActiveObject(clonedObj);
      fabricRef.current.requestRenderAll();
      saveToHistory();
    },
    bringForward: () => {
      const canvas = fabricRef.current;
      const activeObject = canvas?.getActiveObject();
      if (activeObject && canvas) {
        // Handle Fabric 6 rename bringObjectForward
        const method = (canvas as any).bringObjectForward || (canvas as any).bringForward;
        if (typeof method === 'function') {
           method.call(canvas, activeObject);
           canvas.requestRenderAll();
           saveToHistory();
        }
      }
    },
    sendBackwards: () => {
      const canvas = fabricRef.current;
      const activeObject = canvas?.getActiveObject();
      if (activeObject && canvas) {
        // Handle Fabric 6 rename sendObjectBackwards
        const method = (canvas as any).sendObjectBackwards || (canvas as any).sendBackwards;
        if (typeof method === 'function') {
           method.call(canvas, activeObject);
           canvas.requestRenderAll();
           saveToHistory();
        }
      }
    }
  }));

  return (
    <div ref={containerRef} className="w-full aspect-video flex items-center justify-center bg-black overflow-hidden relative">
      {(isEmpty && !hasInteracted) && (
        <div className="absolute inset-0 z-[1] pointer-events-none flex items-center justify-center">
          <p className="text-[11px] font-medium text-zinc-500 select-none uppercase tracking-[0.2em]">Draw here</p>
        </div>
      )}
      <div className="w-full h-full [&>.canvas-container]:!w-full [&>.canvas-container]:!h-full [&>.canvas-container>canvas]:!w-full [&>.canvas-container>canvas]:!h-full">
        <canvas ref={canvasRef} />
      </div>
    </div>
  );
});

import {StrictMode} from 'react';
import {createRoot} from 'react-dom/client';
import App from './App.tsx';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import React, { useState, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { DrawingCanvas, DrawingCanvasHandle } from './components/DrawingCanvas';
import { Tool, RefinedImage, AIModel } from './types';
import { COLORS } from './constants';

const BRUSH_SIZES = [3, 8, 48];
const INITIAL_ADDITIONAL = "Transform this drawing into a photorealistic 3d rendering.";

export default function App() {
  const [tool, setTool] = useState<Tool>('pencil');
  const [color, setColor] = useState(COLORS[0]);
  const [brushSize, setBrushSize] = useState(BRUSH_SIZES[1]);
  const [prompt, setPrompt] = useState('');
  const [additionalPrompt, setAdditionalPrompt] = useState(INITIAL_ADDITIONAL);
  const [isAdditionalExpanded, setIsAdditionalExpanded] = useState(false);
  const [isShortcutsExpanded, setIsShortcutsExpanded] = useState(false);
  const [feed, setFeed] = useState<RefinedImage[]>([]);
  const [isCanvasEmpty, setIsCanvasEmpty] = useState(true);
  const [selectedModel, setSelectedModel] = useState<AIModel>('nano-banana');
  const canvasRef = useRef<DrawingCanvasHandle>(null);

  useEffect(() => {
    const id = 'flow-design-system-setup';
    if (!document.getElementById(id)) {
      const link = document.createElement('link');
      link.id = id;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
      document.head.appendChild(link);

      const style = document.createElement('style');
      style.textContent = `
        html, body, #root {
          background: #000000;
          font-family: 'Google Sans Text', 'Google Sans', sans-serif;
          letter-spacing: 0.1px;
        }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }
        .google-sans-flex { font-family: 'Google Sans Flex', sans-serif; font-feature-settings: 'ss02'; }

        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .animate-spin-fast {
          animation: spin 0.8s linear infinite;
          display: flex !important;
          align-items: center;
          justify-content: center;
          width: 18px;
          height: 18px;
          line-height: 1;
          transform-origin: center center;
          font-variation-settings: 'wght' 300, 'opsz' 20;
        }
      `;
      document.head.appendChild(style);
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isTyping = document.activeElement?.tagName === 'TEXTAREA' || 
                       document.activeElement?.tagName === 'INPUT' ||
                       (document.activeElement as any)?.isContentEditable;
      if (isTyping) return;

      const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
      const modifier = isMac ? e.metaKey : e.ctrlKey;

      if (modifier && e.key === 'z') {
        if (e.shiftKey) canvasRef.current?.redo();
        else canvasRef.current?.undo();
        e.preventDefault();
        return;
      }

      if (modifier) {
        if (e.key.toLowerCase() === 'c') { canvasRef.current?.copy(); return; }
        if (e.key.toLowerCase() === 'v') { canvasRef.current?.paste(); return; }
        if (e.key.toLowerCase() === 'd') { canvasRef.current?.duplicate(); e.preventDefault(); return; }
      }

      if (e.key === 'Delete' || e.key === 'Backspace') {
        canvasRef.current?.deleteSelected();
        return;
      }

      if (e.key === '[') {
        canvasRef.current?.sendBackwards();
        return;
      }
      if (e.key === ']') {
        canvasRef.current?.bringForward();
        return;
      }

      const key = e.key.toLowerCase();
      switch (key) {
        case 'v': setTool('select'); break;
        case 'd': setTool('pencil'); break;
        case 'r': setTool('rectangle'); break;
        case 'o': setTool('circle'); break;
        case 't': setTool('text'); break;
        default: break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const handleRefine = async (existingUserPrompt?: string, existingSketch?: string, modelToUse?: AIModel) => {
    if (!canvasRef.current || isCanvasEmpty) return;

    const userFacingPrompt = existingUserPrompt !== undefined ? existingUserPrompt : prompt.trim();
    const fullPrompt = `${userFacingPrompt} ${additionalPrompt}`.trim();
    const id = crypto.randomUUID();
    const sketchBase64 = existingSketch || canvasRef.current.getCanvasData().split(',')[1];
    const targetModelAlias = modelToUse || selectedModel;

    const placeholder: RefinedImage = {
      id, dataUrl: '', base64: '', sketchBase64, prompt: userFacingPrompt,
      timestamp: Date.now(), status: 'loading', model: targetModelAlias
    };

    setFeed(prev => [placeholder, ...prev]);

    try {
      const { mediaId } = await Flow.upload({
        base64: sketchBase64, mimeType: 'image/png', name: 'Sketch Input'
      });

      const result = await Flow.generate.image({
        prompt: fullPrompt,
        referenceImageMediaIds: [mediaId],
        aspectRatio: '16:9',
        modelDisplayName: targetModelAlias === 'nano-banana-pro' ? 'Nano Banana Pro' : 'Nano Banana 2'
      });

      const dataUrl = `data:${result.mimeType};base64,${result.base64}`;

      setFeed(prev => prev.map(item => 
        item.id === id ? { ...item, dataUrl, base64: result.base64, status: 'ready' } : item
      ));
    } catch (error) {
      console.error('Refinement failed:', error);
      setFeed(prev => prev.map(item => item.id === id ? { ...item, status: 'error' } : item));
    }
  };

  const handleDeleteImage = (id: string) => {
    setFeed(prev => prev.filter(item => item.id !== id));
  };

  const handleAddToCanvas = (dataUrl: string) => {
    canvasRef.current?.addImage(dataUrl);
    setTool('select');
  };

  const handleImportGallery = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        canvasRef.current?.addImage(`data:${media.mimeType};base64,${media.base64}`);
        setTool('select');
      }
    } catch (e) {
      console.error('Media selection failed', e);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-black text-white overflow-hidden select-none tracking-[0.1px]">
      <aside className="w-[60%] min-w-[320px] flex flex-col border-r border-[rgba(218,220,224,0.15)] bg-black">
        <div className="w-full bg-black pt-6 pb-4 px-6">
          <div className="border border-[#595959] overflow-hidden">
            <DrawingCanvas ref={canvasRef} tool={tool} color={color} brushSize={brushSize} onContentChange={(empty) => setIsCanvasEmpty(empty)} />
          </div>
        </div>

        <div className="px-6 pb-6 space-y-4 flex-1 overflow-y-auto no-scrollbar">
          <div className="flex flex-wrap items-center gap-3">
            <div className="bg-black border border-[#595959] rounded-xl p-1.5 flex gap-1 items-center shrink-0">
              <SquareToolButton icon="near_me" active={tool === 'select'} onClick={() => setTool('select')} title="Select (V)" />
              <SquareToolButton icon="edit" active={tool === 'pencil'} onClick={() => setTool('pencil')} title="Pencil (D)" />
              <SquareToolButton icon="rectangle" active={tool === 'rectangle'} onClick={() => setTool('rectangle')} title="Rectangle (R)" />
              <SquareToolButton icon="circle" active={tool === 'circle'} onClick={() => setTool('circle')} title="Circle (O)" />
              <SquareToolButton icon="title" active={tool === 'text'} onClick={() => setTool('text')} title="Text (T)" />
            </div>

            <div className="bg-black border border-[#595959] rounded-xl px-4 flex flex-wrap items-center gap-2 h-[42px] min-w-0">
              {COLORS.map((c) => (
                <button key={c} onClick={() => setColor(c)} className={`w-3.5 h-3.5 rounded-full transition-all border border-white/20 ${color === c ? 'ring-1 ring-white ring-offset-2 ring-offset-black scale-110' : 'hover:scale-105'}`} style={{ backgroundColor: c }} />
              ))}
            </div>

            <div className="bg-black border border-[#595959] rounded-xl p-1.5 flex gap-1 items-center shrink-0 h-[42px]">
              {BRUSH_SIZES.map((size) => (
                <button key={size} onClick={() => setBrushSize(size)} className={`w-[30px] h-[30px] flex items-center justify-center rounded-lg transition-all ${brushSize === size ? 'bg-[#969696] text-black' : 'text-zinc-400 hover:text-white'}`} title={`Brush Size: ${size}`}>
                  <div className={`rounded-full ${brushSize === size ? 'bg-black' : 'bg-white'}`} style={{ width: size === 3 ? 3 : size === 8 ? 7 : 12, height: size === 3 ? 3 : size === 8 ? 7 : 12 }} />
                </button>
              ))}
            </div>

            <div className="bg-black border border-[#595959] rounded-xl p-1.5 flex gap-1 items-center shrink-0">
              <SquareToolButton icon="undo" onClick={() => canvasRef.current?.undo()} title="Undo (Ctrl+Z)" />
              <SquareToolButton icon="redo" onClick={() => canvasRef.current?.redo()} title="Redo (Ctrl+Shift+Z)" />
            </div>

            <div className="bg-black border border-[#595959] rounded-xl p-1.5 flex gap-1 items-center shrink-0">
              <SquareToolButton icon="add_photo_alternate" onClick={handleImportGallery} title="Gallery" />
              <SquareToolButton icon="delete" onClick={() => canvasRef.current?.clear()} title="Clear All" className="text-red-500/80 hover:text-red-500" />
            </div>
          </div>

          <div className="space-y-4 pt-1">
            <div className="relative group">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe your image ..."
                className="w-full h-[68px] p-3 pr-12 rounded-xl bg-transparent border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] focus:outline-none resize-none text-[13px] placeholder:text-zinc-600 transition-colors leading-tight font-normal"
                onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleRefine(); } }}
              />
              <button 
                onClick={() => handleRefine()}
                disabled={isCanvasEmpty}
                className={`absolute bottom-4 right-3.5 flex items-center justify-center transition-all focus:outline-none ${
                  isCanvasEmpty ? 'text-zinc-800 cursor-not-allowed' : 'text-white hover:text-zinc-300 active:scale-95'
                }`}
              >
                <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
              </button>
            </div>

            <div className="flex items-center justify-between h-[26px]">
              <button 
                onClick={() => setIsAdditionalExpanded(!isAdditionalExpanded)}
                className="flex items-center gap-1 text-[11px] font-medium text-[rgba(218,220,224,0.9)] hover:text-white transition-colors h-full"
              >
                <span className="material-symbols-outlined text-[16px]">{isAdditionalExpanded ? 'keyboard_arrow_down' : 'chevron_right'}</span>
                Additional Instructions
              </button>

              <div className="flex items-center gap-2 h-full">
                <div className="flex items-center bg-black border border-[#595959] rounded-xl overflow-hidden h-full">
                  <button onClick={() => setSelectedModel('nano-banana')} className={`px-2.5 h-full text-[9px] font-bold transition-all uppercase tracking-widest ${selectedModel === 'nano-banana' ? 'bg-[#969696] text-black' : 'text-zinc-500 hover:text-white'}`}>FAST</button>
                  <button onClick={() => setSelectedModel('nano-banana-pro')} className={`px-2.5 h-full text-[9px] font-bold transition-all uppercase tracking-widest ${selectedModel === 'nano-banana-pro' ? 'bg-[#969696] text-black' : 'text-zinc-500 hover:text-white'}`}>PRO</button>
                </div>
                <button 
                  onClick={() => setIsShortcutsExpanded(!isShortcutsExpanded)}
                  className={`flex items-center justify-center transition-all focus:outline-none ${isShortcutsExpanded ? 'text-white' : 'text-zinc-500 hover:text-white'}`}
                >
                  <span className="material-symbols-outlined text-[18px]">help</span>
                </button>
              </div>
            </div>

            {isAdditionalExpanded && (
              <div className="animate-in fade-in slide-in-from-top-1">
                <textarea
                  value={additionalPrompt}
                  onChange={(e) => setAdditionalPrompt(e.target.value)}
                  placeholder="Add base instructions (e.g. style, lighting)..."
                  className="w-full h-20 p-3 rounded-xl bg-transparent border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] focus:outline-none resize-none text-[12px] text-zinc-400 placeholder:text-zinc-700 leading-relaxed transition-colors"
                />
              </div>
            )}

            {isShortcutsExpanded && (
              <div className="animate-in fade-in slide-in-from-top-1 bg-black border border-[#595959] rounded-xl p-3 grid grid-cols-2 gap-x-6 gap-y-2">
                <ShortcutItem label="Select" keybind="V" />
                <ShortcutItem label="Pencil" keybind="D" />
                <ShortcutItem label="Rectangle" keybind="R" />
                <ShortcutItem label="Circle" keybind="O" />
                <ShortcutItem label="Text" keybind="T" />
                <ShortcutItem label="Undo" keybind="⌘Z" />
                <ShortcutItem label="Redo" keybind="⇧⌘Z" />
                <ShortcutItem label="Delete" keybind="⌫" />
                <ShortcutItem label="Duplicate" keybind="⌘D" />
                <ShortcutItem label="Generate" keybind="↵" />
                <ShortcutItem label="Bring Forward" keybind="]" />
                <ShortcutItem label="Send Backward" keybind="[" />
              </div>
            )}
          </div>
        </div>
      </aside>

      <main className="w-[40%] overflow-y-auto bg-black p-4 scroll-smooth dark-scrollbar border-l border-[rgba(218,220,224,0.15)]">
        <div className="mx-auto space-y-12">
          {feed.length === 0 ? (
            <div className="h-[60vh] flex flex-col items-center justify-center text-zinc-800">
              <span className="material-symbols-outlined text-[48px] mb-4 opacity-20">image</span>
              <p className="text-[11px] font-medium text-zinc-600 tracking-[0.1em]">Images will appear here</p>
            </div>
          ) : (
            <div className="flex flex-col gap-12">
              {feed.map((item) => (
                <ResultItem 
                  key={item.id} image={item} 
                  onRegenerate={() => handleRefine(item.prompt, item.sketchBase64, item.model)} 
                  onDelete={() => handleDeleteImage(item.id)}
                  onAddToCanvas={() => handleAddToCanvas(item.dataUrl)}
                />
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

const SquareToolButton: React.FC<{ icon: string; active?: boolean; onClick: () => void; title: string; className?: string; }> = ({ icon, active, onClick, title, className = "" }) => (
  <button onClick={onClick} title={title} className={`w-[30px] h-[30px] flex items-center justify-center rounded-lg transition-all focus:outline-none ${active ? 'bg-[#969696] text-black shadow-md' : 'text-zinc-400 hover:bg-white/5 hover:text-white'} ${className}`}>
    <span className="material-symbols-outlined text-[18px]">{icon}</span>
  </button>
);

const ShortcutItem: React.FC<{ label: string; keybind: string }> = ({ label, keybind }) => (
  <div className="flex items-center justify-between gap-2">
    <span className="text-[11px] text-zinc-400 font-medium">{label}</span>
    <span className="text-[10px] text-zinc-300 font-bold bg-white/10 px-1.5 py-0.5 rounded min-w-[20px] text-center">{keybind}</span>
  </div>
);

const ResultItem: React.FC<{ image: RefinedImage; onRegenerate: () => void; onDelete: () => void; onAddToCanvas: () => void; }> = ({ image, onRegenerate, onDelete, onAddToCanvas }) => {
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  const handleSaveToGallery = async () => {
    if (saveStatus !== 'idle' || !image.base64) return;

    setSaveStatus('saving');
    try {
      await Flow.save({
        base64: image.base64,
        mimeType: 'image/png',
        name: `Sketch Refined - ${image.prompt.slice(0, 20)}`
      });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    } catch (err) {
      console.error('Failed to save to gallery', err);
      setSaveStatus('error');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="relative aspect-video bg-black overflow-hidden ring-1 ring-white/10 rounded-lg group">
        {image.status === 'loading' ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-black">
            <div className="flex items-center gap-1.5">
              <div className="w-1 h-1 bg-white/20 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-1 h-1 bg-white/40 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-1 h-1 bg-white/60 rounded-full animate-bounce"></div>
            </div>
            <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">GENERATING</span>
          </div>
        ) : image.status === 'error' ? (
          <div className="absolute inset-0 flex items-center justify-center bg-black">
            <span className="text-zinc-600 font-bold text-[10px]">Refinement Failed</span>
          </div>
        ) : (
          <img src={image.dataUrl} className="w-full h-full object-contain" alt="" />
        )}
      </div>
      <div className="mt-3 flex items-start justify-between gap-4 px-1">
        <div className="flex-1 space-y-1">
          <p className="text-[11px] text-zinc-400 leading-normal font-medium">
            {image.prompt || "No custom prompt"}
          </p>
          <span className="px-2 py-0.5 rounded-full text-[8px] font-bold bg-white/5 text-zinc-500">
            {image.model === 'nano-banana-pro' ? 'PRO' : 'FAST'}
          </span>
        </div>
        {image.status === 'ready' && (
          <div className="flex items-center gap-1 shrink-0">
            <ResultAction icon="add_box" title="Add to Canvas" onClick={onAddToCanvas} />
            <ResultAction icon="refresh" title="Regenerate" onClick={onRegenerate} />
            <ResultAction 
              icon={
                saveStatus === 'saving' ? 'progress_activity' : 
                saveStatus === 'saved' ? 'check' : 
                saveStatus === 'error' ? 'error' : 
                'download'
              } 
              title={saveStatus === 'saved' ? 'Saved to Gallery' : 'Save to Gallery'} 
              onClick={handleSaveToGallery} 
              iconClassName={saveStatus === 'saving' ? 'animate-spin-fast' : ''}
              className={
                saveStatus === 'saved' ? 'text-green-500 hover:text-green-400' : 
                saveStatus === 'error' ? 'text-red-500' : 
                saveStatus === 'saving' ? 'text-white' : ''
              }
            />
            <ResultAction icon="delete" title="Delete" onClick={onDelete} className="hover:text-red-400" />
          </div>
        )}
      </div>
    </div>
  );
};

const ResultAction: React.FC<{ 
  icon: string; 
  title: string; 
  onClick: () => void; 
  className?: string;
  iconClassName?: string;
}> = ({ icon, title, onClick, className = "", iconClassName = "" }) => (
  <button onClick={onClick} title={title} className={`p-1.5 text-zinc-500 hover:text-white transition-colors focus:outline-none flex items-center justify-center ${className}`}>
    <span className={`material-symbols-outlined text-[18px] ${iconClassName}`}>{icon}</span>
  </button>
);
